        ChatID = "3",
        MessageIntervals = 1,
        Content = "AvgCommunicate_66981_Content_4|没错，人类是依托肉体而生的存在，而情感托生于本能的反应。"
      }),
      readonly({
        DialogType = "DialogType1",
        TalkRole = {
          1054,
