      readonly({
        DialogType = "DialogType1",
        TalkRole = {
          1171,
          nil,
          "Smile"
        },
        ChatID = "8",
        MessageIntervals = 1,
        Content = "AvgCommunicate_84109_Content_8|是的，我也很开心，并且希望日后能经常和您出去放松。"
      }),
      readonly({
        DialogType = "DialogType4",
        TalkRole = {1001},
        ChatID = "9",
        MessageIntervals = 1,
        Option = "AvgCommunicate_84109_Option_9|没问题",
