        ChatID = "10",
        MessageIntervals = 0.5,
        Option = "AvgCommunicate_134103_Option_10|不是误会。",
        Content = "AvgCommunicate_134103_Content_10|你知道吗？阿格里帕常常说羡慕弥利亚姆。"
      }),
      readonly({
