      }),
      readonly({
        DialogType = "DialogType1",
        TalkRole = {
          1159,
          nil,
          "Surprised"
        },
        ChatID = "12",
        MessageIntervals = 1,
        Content = "AvgCommunicate_134103_Content_12|羡慕……"
