      }),
      readonly({
        DialogType = "DialogType1",
        TalkRole = {1001},
        ChatID = "11",
        MessageIntervals = 1,
        Content = "AvgCommunicate_134115_Content_11|你能看到这些，我为你感到开心，弥利亚姆！"
