        TalkRole = {1001},
        ChatID = "17",
        MessageIntervals = 0.5,
        Option = "AvgCommunicate_134115_Option_17|也行吧……",
        Content = "AvgCommunicate_134115_Content_17|虽然过程感觉不太对劲……不过也算是个不错的结果。"
      })
    })
