      readonly({
        DialogType = "DialogType1",
        TalkRole = {1244},
        ChatID = "11",
        MessageIntervals = 1,
        Content = "AvgCommunicate_134250_Content_11|你其实一直在表演，就像那些奴隶主一样。"
      }),
      readonly({
        DialogType = "DialogType4",
