        TalkRole = {
          1142,
          nil,
          "Sad"
        },
        ChatID = "14",
        MessageIntervals = 1,
        Content = "AvgCommunicate_134249_Content_14|诶？皮鞭都不用？好失望。"
      }),
      readonly({
        DialogType = "DialogType1",
        TalkRole = {1001},
        ChatID = "15",
        MessageIntervals = 1,
        Emoji = 54130
      }),
      readonly({
