        ChatID = "16",
        MessageIntervals = 1,
        Content = "AvgCommunicate_134249_Content_16|……呃，如果你实在需要的话，要么去找找潘狄娅……"
      }),
      readonly({
        DialogType = "DialogType1",
        TalkRole = {
          1142,
          nil,
          "Smile"
        },
        ChatID = "17",
        MessageIntervals = 0.5,
        Content = "AvgCommunicate_134249_Content_17|呵呵。"
