        ChatID = "13",
        MessageIntervals = 1,
        Content = "AvgCommunicate_134277_Content_13|我来到这个世界该不会真是命运的安排吧？"
      }),
      readonly({
        DialogType = "DialogType1",
        TalkRole = {1001},
