        Emoji = 123556
      }),
      readonly({
        DialogType = "DialogType1",
        TalkRole = {
          2202,
          nil,
          "Shy"
        },
        ChatID = "15",
        MessageIntervals = 1.5,
        Content = "AvgCommunicate_134277_Content_15|总之，托你的福，我触摸到了在你们这个世界，属于我的「极限」。"
      }),
      readonly({
        DialogType = "DialogType1",
